import { motion } from 'framer-motion'
import { Sparkles, MapPin } from 'lucide-react'
import { BrandLogo } from './BrandLogo'
import { useAuthStore, useMenuStore } from '@/store'
import { useIsShopOpen, useNextOpeningTime } from '@/features/config/hooks/useShopConfig'
import { hapticHeavy } from '@/utils/haptics'
import { SearchBar } from '@/features/menu/components/SearchBar'

export function AppHeader() {
  const { user, isGuest } = useAuthStore()
  const { isSearchOpen } = useMenuStore()
  const { data: isOpen } = useIsShopOpen()
  const { data: nextOpening } = useNextOpeningTime()

  return (
    <header className="sticky top-0 z-[60] safe-area-pt">
      {/* Frosted Glass Base */}
      <div
        className="absolute inset-0"
        style={{
          background: 'rgba(255, 255, 255, 0.94)',
          backdropFilter: 'blur(32px) saturate(180%)',
          WebkitBackdropFilter: 'blur(32px) saturate(180%)',
          borderBottom: '1px solid rgba(15, 23, 42, 0.06)',
          boxShadow: '0 4px 20px rgba(15, 23, 42, 0.03)'
        }}
      />

      <div className="max-w-md mx-auto px-4 py-3 relative z-10 space-y-2.5">
        {/* ─── TOP ROW: Brand Logo & Actions ─── */}
        <div className="flex items-center justify-between">
          {/* Brand Logo */}
          <BrandLogo size="md" showTagline={true} />

          {/* Right Action Hub */}
          <div className="flex items-center gap-2">
            {/* Search Bar Toggle */}
            <SearchBar />

            {/* Guest LINE Login Button */}
            {isGuest && (
              <motion.button
                type="button"
                whileHover={{ scale: 1.04 }}
                whileTap={{ scale: 0.94 }}
                onClick={async () => {
                  hapticHeavy()
                  try {
                    const { loginWithLine } = await import('@/lib/auth')
                    await loginWithLine()
                  } catch (e) { console.error(e) }
                }}
                className="flex items-center gap-1.5 px-3.5 py-2 rounded-full font-black text-xs text-white shadow-sm cursor-pointer transition-all"
                style={{
                  background: 'linear-gradient(135deg, #06C755 0%, #00B900 100%)',
                  boxShadow: '0 4px 14px rgba(6, 199, 85, 0.35)',
                }}
              >
                {/* LINE Chat Bubble SVG Icon */}
                <svg className="w-3.5 h-3.5 fill-white" viewBox="0 0 24 24">
                  <path d="M24 10.304c0-5.369-5.383-9.738-12-9.738-6.616 0-12 4.369-12 9.738 0 4.814 4.269 8.846 10.019 9.587.39.085.922.26 1.057.595.122.302.08.774.039 1.08l-.171 1.026c-.053.313-.243 1.226 1.074.668 1.317-.557 7.108-4.225 9.7-7.234 1.554-1.745 2.282-3.524 2.282-5.722z"/>
                </svg>
                <span>เข้าสู่ระบบ</span>
              </motion.button>
            )}

            {/* Logged in User Pill */}
            {!isGuest && user && (
              <motion.div
                whileTap={{ scale: 0.95 }}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-full border bg-amber-50/80 shadow-sm cursor-pointer"
                style={{ borderColor: 'rgba(245, 158, 11, 0.30)' }}
              >
                <Sparkles className="w-3.5 h-3.5 text-amber-500" />
                <span className="font-black text-xs text-amber-800 num-display">
                  {user.points || 0} <span className="text-[10px] text-amber-600 font-bold">pts</span>
                </span>
              </motion.div>
            )}
          </div>
        </div>

        {/* ─── BOTTOM ROW: Location & Live Status Pill ─── */}
        {!isSearchOpen && (
          <div className="flex items-center justify-between pt-0.5">
            {/* Delivery/Kitchen Location */}
            <div className="flex items-center gap-1 text-[11px] font-bold text-slate-500">
              <MapPin className="w-3.5 h-3.5 text-orange-500" />
              <span className="truncate max-w-[170px]">ครัวกะเพรา 52 • สาขาหลัก</span>
            </div>

            {/* Live Operational Status Badge */}
            <div
              className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-black border"
              style={
                isOpen !== false
                  ? {
                      background: 'rgba(22, 163, 74, 0.08)',
                      borderColor: 'rgba(22, 163, 74, 0.22)',
                      color: '#15803D',
                    }
                  : {
                      background: 'rgba(245, 158, 11, 0.10)',
                      borderColor: 'rgba(245, 158, 11, 0.25)',
                      color: '#B45309',
                    }
              }
            >
              <span className="relative flex h-2 w-2">
                <span
                  className={`animate-ping absolute inline-flex h-full w-full rounded-full opacity-75 ${
                    isOpen !== false ? 'bg-emerald-400' : 'bg-amber-400'
                  }`}
                />
                <span
                  className={`relative inline-flex rounded-full h-2 w-2 ${
                    isOpen !== false ? 'bg-emerald-500' : 'bg-amber-500'
                  }`}
                />
              </span>
              <span>
                {isOpen !== false ? 'เปิดรับออเดอร์' : `ปิด (เปิด ${nextOpening || '08:00'})`}
              </span>
            </div>
          </div>
        )}
      </div>
    </header>
  )
}
